"""Intent tests for risk.summary_stats (RISK-04, TC-07)."""

from __future__ import annotations

import pytest

from risk import Returns, TickerSummary, VolSeries, summary_stats


def _returns(payload: dict) -> Returns:
    return Returns(
        base_date=payload["base_date"],
        dates=tuple(payload["dates"]),
        tickers=tuple(payload["tickers"]),
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def _vol(payload: dict) -> VolSeries:
    return VolSeries(
        returns=_returns(payload["returns"]),
        window=payload["window"],
        annualized=payload["annualized"],
        values={t: tuple(v) for t, v in payload["values"].items()},
    )


def _tc07(golden) -> tuple[dict[str, TickerSummary], dict[str, dict], float]:
    inp, expected = golden("risk", "TC-07")
    result = summary_stats(_vol(inp["vol"]))
    by_ticker = {row.ticker: row for row in result}
    wanted = {row["ticker"]: row for row in expected["summary"]}
    return by_ticker, wanted, expected["tol"]


@pytest.mark.intent
def test_tc07_one_summary_per_ticker(golden):
    inp, expected = golden("risk", "TC-07")
    result = summary_stats(_vol(inp["vol"]))
    assert isinstance(result, tuple)
    assert all(isinstance(row, TickerSummary) for row in result)
    assert sorted(row.ticker for row in result) == sorted(r["ticker"] for r in expected["summary"])
    assert len(result) == len(expected["summary"])


@pytest.mark.intent
@pytest.mark.parametrize("ticker", ["X", "Y"])
def test_tc07_annualized_return_is_252_times_mean(golden, ticker):
    got, wanted, tol = _tc07(golden)
    assert got[ticker].ann_return == pytest.approx(wanted[ticker]["ann_return"], abs=tol)


@pytest.mark.intent
@pytest.mark.parametrize("ticker", ["X", "Y"])
def test_tc07_annualized_vol_is_sqrt252_sample_stdev(golden, ticker):
    got, wanted, tol = _tc07(golden)
    assert got[ticker].ann_vol == pytest.approx(wanted[ticker]["ann_vol"], abs=tol)


@pytest.mark.intent
@pytest.mark.parametrize("ticker", ["X", "Y"])
def test_tc07_sharpe_is_ratio_zero_when_flat(golden, ticker):
    got, wanted, tol = _tc07(golden)
    assert got[ticker].sharpe == pytest.approx(wanted[ticker]["sharpe"], abs=tol)


@pytest.mark.intent
@pytest.mark.parametrize("ticker", ["X", "Y"])
def test_tc07_last_vol_is_last_rolling_value(golden, ticker):
    got, wanted, tol = _tc07(golden)
    assert got[ticker].last_vol is not None
    assert got[ticker].last_vol == pytest.approx(wanted[ticker]["last_vol"], abs=tol)


@pytest.mark.intent
def test_fewer_than_two_returns_raises(contract_sample):
    payload = contract_sample("risk.VolSeries")
    returns = payload["returns"]
    one = {
        "returns": {
            "base_date": returns["base_date"],
            "dates": returns["dates"][:1],
            "tickers": returns["tickers"],
            "values": {t: v[:1] for t, v in returns["values"].items()},
        },
        "window": payload["window"],
        "annualized": payload["annualized"],
        "values": {t: v[:1] for t, v in payload["values"].items()},
    }
    with pytest.raises(ValueError, match=r"(?i)two|2"):
        summary_stats(_vol(one))

